import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, time, uniform, texture, normalMap } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // ============================================================================
  // PALETTE & DESIGN TOKENS
  // ============================================================================
  const colors = {
    background: 0x0b0b10,
    surface: 0x14141a,
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
  };

  // ============================================================================
  // GEOMETRY & MATERIAL SETUP
  // ============================================================================

  // Plate dimensions: 1.9 x 1.2 units (16:10 aspect)
  const plateWidth = 1.9;
  const plateHeight = 1.2;
  const platePitch = 1.5; // vertical spacing between plates
  const numPlates = 6;
  const columnOffsetX = 0.9;

  // Load the image texture
  let imageTexture = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    imageTexture = tex;
    imageTexture.colorSpace = THREE.SRGBColorSpace;
    updatePlateTextures();
  });

  // Store plate meshes for update
  const plates = [];

  function updatePlateTextures() {
    if (!imageTexture) return;
    for (let i = 0; i < plates.length; i++) {
      if (plates[i].material.mapNode) {
        plates[i].material.mapNode = texture(imageTexture);
        plates[i].material.needsUpdate = true;
      }
    }
  }

  // Create plate geometry (simple plane with bevel frame concept)
  const plateGeometry = new THREE.PlaneGeometry(plateWidth, plateHeight, 16, 16);

  // Create each plate
  for (let i = 0; i < numPlates; i++) {
    // Main plate surface with PBR
    const plateMaterial = new MeshStandardNodeMaterial({
      color: colors.paper,
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
      side: THREE.FrontSide,
    });

    // Apply texture node if available
    if (imageTexture) {
      plateMaterial.colorNode = texture(imageTexture);
    }

    const plateMesh = new THREE.Mesh(plateGeometry, plateMaterial);
    plateMesh.position.set(columnOffsetX, -i * platePitch, 0);
    plateMesh.userData.plateIndex = i;
    group.add(plateMesh);
    plates.push(plateMesh);

    // Machined ink bevel frame (0.03 units wide)
    const bevelThickness = 0.03;
    const bevelGeometry = new THREE.EdgesGeometry(plateGeometry);
    const bevelMaterial = new MeshBasicNodeMaterial({
      color: colors.ink,
      linewidth: 2,
    });

    // Create a slightly larger plane for the frame
    const frameGeometry = new THREE.PlaneGeometry(
      plateWidth + bevelThickness * 2,
      plateHeight + bevelThickness * 2,
      2,
      2
    );
    const frameMaterial = new MeshStandardNodeMaterial({
      color: colors.ink,
      roughness: 0.5,
      metalness: 0.5,
      emissive: 0x000000,
    });
    const frameMesh = new THREE.Mesh(frameGeometry, frameMaterial);
    frameMesh.position.z = -0.01;
    plateMesh.add(frameMesh);
  }

  // ============================================================================
  // ACCENT STRIP (left edge, emissive red)
  // ============================================================================
  const stripWidth = 0.03;
  const stripGeometry = new THREE.PlaneGeometry(stripWidth, plateHeight + 0.1, 2, 16);
  const stripMaterial = new MeshStandardNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.4,
    metalness: 0.3,
    roughness: 0.4,
  });
  const stripMesh = new THREE.Mesh(stripGeometry, stripMaterial);
  stripMesh.position.set(columnOffsetX - plateWidth / 2 - stripWidth / 2, 0, 0.02);
  stripMesh.userData.isAccentStrip = true;
  group.add(stripMesh);

  // ============================================================================
  // BACKDROP PLANE (7x6 units, gradient from visual spec)
  // ============================================================================
  const backdropGeometry = new THREE.PlaneGeometry(7, 6, 2, 2);
  const backdropMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
  });

  // Create gradient via uv-based color mixing
  const gradientColor = mix(
    vec3(colors.background / 0xffffff),
    vec3(colors.surface / 0xffffff),
    uv().y
  );
  backdropMaterial.colorNode = mix(
    vec3(0.04, 0.04, 0.06), // #0b0b10 normalized
    vec3(0.08, 0.08, 0.1), // #14141a normalized
    uv().y
  );

  const backdropMesh = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdropMesh.position.z = -2.5;
  group.add(backdropMesh);

  // ============================================================================
  // TEXT: HEADLINE + CAPTIONS
  // ============================================================================
  const headlineText = ctx.fontAtlas.createText('Inside the atelier', {
    fontSize: 68,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: -0.005 * 68,
  });
  headlineText.position.set(-1.6, 1.9, 0);
  group.add(headlineText);

  // Caption labels for each plate (fade in/out dynamically based on focus)
  const captions = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE',
  ];

  const captionMeshes = [];
  for (let i = 0; i < captions.length; i++) {
    const captionText = ctx.fontAtlas.createText(captions[i], {
      fontSize: 18,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: 0.08 * 18,
    });
    captionText.position.set(-1.6, -i * platePitch - 0.5, 0.1);
    captionText.userData.captionIndex = i;
    captionText.userData.targetOpacity = i === 0 ? 1 : 0.3;
    group.add(captionText);
    captionMeshes.push(captionText);
  }

  // ============================================================================
  // SCROLL INTERACTION & WEIGHTED MOTION
  // ============================================================================
  const state = {
    scrollY: 0,
    velocityY: 0,
    targetY: 0,
    isDamping: false,
    focusedPlateIndex: 0,
  };

  const scrollConfig = {
    unitsPerScroll: 1.5,
    dampingFactor: 0.12,
    settleDuration: 0.9,
    settleEasing: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
  };

  let scrollTimeline = null;

  const onScroll = (event) => {
    // Accumulate scroll velocity
    const deltaScroll = (event.deltaY || 0) * 0.001;
    state.velocityY += deltaScroll * scrollConfig.unitsPerScroll;

    // Kill existing timeline if still damping
    if (scrollTimeline) {
      scrollTimeline.kill();
    }

    // Apply damping and settle
    scrollTimeline = gsap.to(state, {
      velocityY: 0,
      duration: scrollConfig.settleDuration,
      ease: scrollConfig.settleEasing,
      onUpdate: () => {
        state.scrollY += state.velocityY * 0.016; // frame delta approx
        state.targetY = state.scrollY;

        // Clamp to prevent excessive wraparound
        const maxScroll = platePitch * numPlates;
        if (state.targetY < 0) state.targetY = 0;
        if (state.targetY > maxScroll) state.targetY = maxScroll;

        updateColumnPosition();
      },
    });
  };

  function updateColumnPosition() {
    // Update plate positions (looping)
    const loopHeight = platePitch * numPlates;
    for (let i = 0; i < plates.length; i++) {
      const baseY = -i * platePitch - state.targetY;
      const wrappedY = baseY % loopHeight;
      plates[i].position.y = wrappedY;
    }

    // Update caption positions
    for (let i = 0; i < captionMeshes.length; i++) {
      const baseY = -i * platePitch - state.targetY - 0.5;
      const loopHeight = platePitch * numPlates;
      const wrappedY = baseY % loopHeight;
      captionMeshes[i].position.y = wrappedY;
    }

    // Update focused plate (nearest to y=0)
    let closestIndex = 0;
    let closestDist = Infinity;
    for (let i = 0; i < plates.length; i++) {
      const dist = Math.abs(plates[i].position.y);
      if (dist < closestDist) {
        closestDist = dist;
        closestIndex = i;
      }
    }
    state.focusedPlateIndex = closestIndex;

    // Scale & opacity animation for focused plate
    for (let i = 0; i < plates.length; i++) {
      if (i === closestIndex) {
        gsap.to(plates[i].scale, {
          x: 1.06,
          y: 1.06,
          duration: 0.35,
          ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
        });
        gsap.to(captionMeshes[i], {
          opacity: 1,
          duration: 0.5,
          ease: 'power2.out',
        });
      } else {
        gsap.to(plates[i].scale, {
          x: 1.0,
          y: 1.0,
          duration: 0.35,
          ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
        });
        gsap.to(captionMeshes[i], {
          opacity: 0.3,
          duration: 0.5,
          ease: 'power2.out',
        });
      }
    }

    // Accent strip position (follow focused plate)
    stripMesh.position.y = plates[closestIndex].position.y;
  }

  // Attach scroll handler
  group.userData.handlers = {
    scroll: onScroll,
  };

  // ============================================================================
  // CINEMATIC PRIMITIVE: FLY-THROUGH
  // ============================================================================
  const flyThroughResult = ctx.primitives['fly-through'](group, {
    depthUnits: 2.5,
    trigger: 'scroll',
  });

  // ============================================================================
  // LIGHTING
  // ============================================================================
  // Key light
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 2, 1.5);
  keyLight.castShadow = true;
  group.add(keyLight);

  // Rim/accent light (red-tinted, opposite side)
  const rimLight = new THREE.DirectionalLight(colors.accent, 0.6);
  rimLight.position.set(-2.5, 1, 1.2);
  group.add(rimLight);

  // Ambient fill
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
  group.add(ambientLight);

  // ============================================================================
  // CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    if (scrollTimeline) scrollTimeline.kill();
    if (flyThroughResult?.cleanup) flyThroughResult.cleanup();

    // Dispose geometries & materials
    plateGeometry.dispose();
    stripGeometry.dispose();
    backdropGeometry.dispose();

    plates.forEach((p) => {
      p.material.dispose();
      p.children.forEach((c) => c.material?.dispose());
    });
    stripMaterial.dispose();
    backdropMaterial.dispose();
    frameMaterial.dispose();
  };

  return group;
}
